mapper.select:
select distinct u.user_id, u.username, u.nickname, u.email, u.phone, u.status, u.create_time from sys_user u left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = 0 and r.role_id = #{roleId}
AND u.username like concat('%', #{user.username}, '%')
AND u.phone like concat('%', #{user.phone}, '%')
